import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {insightScenario} from '../../server/test/insight-helpers.js';
async function cliContext(scenario,fn){
  const created=(await scenario.api('POST','/tokens',{name:'Insight CLI',scopes:['*']})).data;
  const cli=args=>new Promise((resolve,reject)=>{
    const child=spawn(process.execPath,[fileURLToPath(new URL('../bin/crew.js',import.meta.url)),...args,'--url',scenario.server.url,'--token',created.token,'--json']);
    let stdout='',stderr='';const timer=setTimeout(()=>{child.kill('SIGKILL');reject(new Error('CLI test deadline'));},10000);
    child.stdout.on('data',chunk=>stdout+=chunk);child.stderr.on('data',chunk=>stderr+=chunk);
    child.on('error',error=>{clearTimeout(timer);reject(error);});child.on('close',code=>{clearTimeout(timer);try{resolve({code,data:stdout?JSON.parse(stdout):null,stderr});}catch(error){reject(error);}});
  });
  return fn(cli);
}
test('actual feed CLI traverses pages and creates/mutes personal watches',()=>insightScenario(s=>cliContext(s,async cli=>{
  const list=await cli(['feed','list','--org',s.org.id,'--limit','1','--all']);assert.equal(list.code,0,list.stderr);assert(list.data.items.some(event=>event.entityId===s.issue.id));
  assert.equal((await cli(['feed','watch','project',s.project.id])).code,0);
  const watched=await cli(['feed','subscriptions','--org',s.org.id]);assert(watched.data.items.some(item=>item.targetType==='project'));
  assert.equal((await cli(['feed','unwatch','project',s.project.id])).code,0);
  assert.equal((await cli(['feed','watch','unknown','x'])).code,1);
})));
test('actual inbox CLI reads marks filters preferences and queues local digests',()=>insightScenario(s=>cliContext(s,async cli=>{
  await s.member('PATCH','/issues/'+s.issue.id,{title:'CLI inbox update'});
  const inbox=await cli(['inbox','list','--org',s.org.id,'--state','unread']);assert.equal(inbox.code,0,inbox.stderr);const id=inbox.data.items[0].id;
  assert.equal((await cli(['inbox','read',id])).data.notification.read,true);
  assert.equal((await cli(['inbox','unread',id])).data.notification.read,false);
  assert.equal((await cli(['inbox','digest','--org',s.org.id])).data.count,1);
  assert.equal((await cli(['inbox','preferences','--org',s.org.id,'--email','false'])).data.preferences.emailEnabled,false);
  assert.equal((await cli(['inbox','mark-all','--org',s.org.id])).code,1);
  assert.equal((await cli(['inbox','mark-all','--org',s.org.id,'--yes'])).data.changed,1);
  assert.equal((await cli(['inbox','list','--org',s.org.id,'--state','unread'])).data.items.length,0);
  assert.equal((await cli(['feed','--help'])).code,0);assert.equal((await cli(['inbox','--help'])).code,0);
})));

import {authenticate} from './middleware/auth.js';
import {canSeeActivity,publicActivity} from '../modules/insight/activity.js';
export function liveRequest(ctx,source) {
  const current={headers:source.headers,method:'GET'};
  let failure;
  authenticate(ctx)(current,null,error=>{failure=error;});
  if(failure||!current.user)return null;
  try {
    ctx.permissions.scope(current,'insight:read');
    if(source.query.orgId)ctx.permissions.assertOrg(current,source.query.orgId,'org:read');
    if(source.query.projectId)ctx.permissions.assertProject(current,source.query.projectId,'insight:read');
    return current;
  } catch { return null; }
}
export function registerSse(ctx) {
  const connections=new Set();
  ctx.sseRegistered=true;
  ctx.app.get('/api/v1/events',ctx.requireAuth,(req,res)=>{
    ctx.permissions.scope(req,'insight:read');
    if(req.query.orgId)ctx.permissions.assertOrg(req,req.query.orgId,'org:read');
    if(req.query.projectId)ctx.permissions.assertProject(req,req.query.projectId,'insight:read');
    res.status(200).set({'Content-Type':'text/event-stream','Cache-Control':'no-cache, no-store','Connection':'keep-alive','X-Accel-Buffering':'no'});
    res.flushHeaders();
    let closed=false,unsubscribe=()=>{},timer;
    const close=()=>{
      if(closed)return;
      closed=true;clearInterval(timer);unsubscribe();connections.delete(close);
      req.off('close',close);res.off('error',close);res.off('close',close);
      if(!res.writableEnded)res.end();
    };
    const write=(event,data,id)=>{
      if(closed||res.destroyed)return close();
      const frame=(id?'id: '+id+'\n':'')+'event: '+event+'\ndata: '+JSON.stringify(data)+'\n\n';
      if(!res.write(frame))close();
    };
    const delivery=row=>{
      const current=liveRequest(ctx,req);
      if(!current){close();return;}
      if(!row||!canSeeActivity(ctx,current.user.id,row))return;
      if(req.query.orgId&&row.org_id!==req.query.orgId)return;
      if(req.query.projectId&&row.project_id!==req.query.projectId)return;
      write('activity',publicActivity(row),row.id);
    };
    unsubscribe=ctx.bus.subscribe(event=>{
      if(!liveRequest(ctx,req)){close();return;}
      delivery(ctx.db.prepare('SELECT * FROM activity WHERE id=?').get(event.id));
    });
    connections.add(close);
    req.on('close',close);res.on('error',close);res.on('close',close);
    write('ready',{userId:req.user.id,time:ctx.now()});
    const last=req.headers['last-event-id']??req.query.lastEventId;
    if(last){
      const anchor=ctx.db.prepare('SELECT * FROM activity WHERE id=?').get(last);
      if(anchor&&canSeeActivity(ctx,req.user.id,anchor)){
        const rows=ctx.db.prepare('SELECT * FROM activity WHERE created_at>? OR (created_at=? AND id>?) ORDER BY created_at,id').all(anchor.created_at,anchor.created_at,anchor.id)
          .filter(row=>canSeeActivity(ctx,req.user.id,row))
          .filter(row=>!req.query.orgId||row.org_id===req.query.orgId)
          .filter(row=>!req.query.projectId||row.project_id===req.query.projectId).slice(0,201);
        if(rows.length>200)write('reset',{reason:'Refresh the activity feed to load missed updates'});
        else for(const row of rows)delivery(row);
      }else write('reset',{reason:'Refresh the activity feed to resume'});
    }
    if(closed)return;
    timer=setInterval(()=>{
      if(!liveRequest(ctx,req))close();
      else write('heartbeat',{time:ctx.now()});
    },15000);
    timer.unref();
  });
  (ctx.cleanups??=[]).push(()=>{for(const close of [...connections])close();});
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {setTimeout as delay} from 'node:timers/promises';
import {insightScenario} from './insight-helpers.js';
async function openStream(server,route,headers={}) {
  const controller=new AbortController();
  const timer=setTimeout(()=>controller.abort(new Error('SSE test deadline')),2500);
  const response=await fetch(server.url+'/api/v1/events'+route,{headers,signal:controller.signal});
  assert.equal(response.status,200);
  const reader=response.body.getReader(),decoder=new TextDecoder();
  let pending='';
  return {response,async next(){
    for(;;){
      const at=pending.indexOf('\n\n');
      if(at>=0){const frame=pending.slice(0,at);pending=pending.slice(at+2);const lines=frame.split('\n');return {event:lines.find(line=>line.startsWith('event: '))?.slice(7),data:JSON.parse(lines.find(line=>line.startsWith('data: ')).slice(6))};}
      const chunk=await reader.read();if(chunk.done)return null;pending+=decoder.decode(chunk.value,{stream:true});
    }
  },close(){clearTimeout(timer);controller.abort();reader.cancel().catch(()=>{});}};
}
test('real SSE emits sanitized visible activity and releases subscription after disconnect',()=>insightScenario(async({server,api,member,org,issue,cookie})=>{
  const baseline=server.ctx.bus.listenerCount;
  const stream=await openStream(server,'?orgId='+org.id,{cookie});
  try{
    assert.equal((await stream.next()).event,'ready');assert.equal(server.ctx.bus.listenerCount,baseline+1);
    await member('PATCH','/issues/'+issue.id,{title:'Live title'});
    const update=await stream.next();assert.equal(update.event,'activity');assert.equal(update.data.after.title,'Live title');assert.equal(update.data.entityId,issue.id);
  }finally{stream.close();}
  for(let attempt=0;attempt<20&&server.ctx.bus.listenerCount!==baseline;attempt++)await delay(5);
  assert.equal(server.ctx.bus.listenerCount,baseline);
}));
test('SSE rejects anonymous and insufficient scope credentials before streaming',()=>insightScenario(async({server,api,org})=>{
  const anonymous=await fetch(server.url+'/api/v1/events?orgId='+org.id);assert.equal(anonymous.status,401);
  const token=(await api('POST','/tokens',{name:'No insight',scopes:['self:read']})).data.token;
  const denied=await fetch(server.url+'/api/v1/events?orgId='+org.id,{headers:{Authorization:'Bearer '+token}});assert.equal(denied.status,403);
}));
test('SSE closes immediately when its browser session is revoked',()=>insightScenario(async({server,api,org,cookie})=>{
  const sessions=(await api('GET','/auth/sessions')).data.items,current=sessions.find(session=>session.current);
  const stream=await openStream(server,'?orgId='+org.id,{cookie});
  try{await stream.next();assert.equal((await api('DELETE','/auth/sessions/'+current.id)).status,200);assert.equal(await stream.next(),null);}
  finally{stream.close();}
}));
test('SSE reauthenticates token and closes on token revocation',()=>insightScenario(async({server,api,org})=>{
  const created=(await api('POST','/tokens',{name:'Live',scopes:['*']})).data;
  const stream=await openStream(server,'?orgId='+org.id,{Authorization:'Bearer '+created.token});
  try{await stream.next();await api('DELETE','/tokens/'+created.personalToken.id);assert.equal(await stream.next(),null);}
  finally{stream.close();}
}));
test('SSE rechecks granted project access and ends without delivering revoked content',()=>insightScenario(async({server,api,member,memberUser,org,project,issue})=>{
  await api('PATCH','/orgs/'+org.id+'/members/'+memberUser.id,{role:'guest'});
  await api('POST','/projects/'+project.id+'/guests',{userId:memberUser.id});
  const memberCookie=(await member('GET','/me')).cookie;
  const stream=await openStream(server,'?orgId='+org.id+'&projectId='+project.id,{cookie:memberCookie});
  try{await stream.next();await api('DELETE','/projects/'+project.id+'/guests/'+memberUser.id);await api('PATCH','/issues/'+issue.id,{title:'No longer visible'});assert.equal(await stream.next(),null);}
  finally{stream.close();}
}));
test('application cleanup closes live streams and unregisters all event listeners',()=>insightScenario(async({server,org,cookie})=>{
  const stream=await openStream(server,'?orgId='+org.id,{cookie});
  try{await stream.next();server.ctx.cleanup();assert.equal(await stream.next(),null);assert.equal(server.ctx.bus.listenerCount,0);server.ctx.cleanup();}
  finally{stream.close();}
}));
